-- ============================================================================
-- CBI Rial Banking Fees 1405 - PROVISIONAL versioned import
-- Workbook SHA256: bbe79ea223fabbfcddd83a402a70bc87f9c3fb3ad3d0de01369155240e4bd15e
-- PDF SHA256     : ea2e6a22e3b92b7ea6ef5da8cd6bfa20f918d0fc069c2e1bd46b89167a993e14
-- Official circular number/date were not provided. This dataset is intentionally marked PROVISIONAL.
-- Replaces only the non-electronic rial-banking subset of CBI 1404; electronic-fee definitions remain untouched.
-- ============================================================================
SET DEFINE OFF;
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;
ALTER SESSION SET CURRENT_SCHEMA = FEE;

PROMPT [CBI1405-P] Validating prerequisite CBI 1404 import ...
DECLARE v NUMBER; BEGIN SELECT COUNT(*) INTO v FROM FEE_REGULATORY_SOURCE WHERE SOURCE_CODE='CBI_FEE_1404_04_35500'; IF v<>1 THEN RAISE_APPLICATION_ERROR(-20201,'CBI 1404 source missing/duplicated'); END IF; END;
/

PROMPT [CBI1405-P] Upserting provisional regulatory source ...
MERGE INTO FEE_REGULATORY_SOURCE t
USING (SELECT 'CBI_RIAL_FEE_1405_PROVISIONAL' SOURCE_CODE, 'CIRCULAR' SOURCE_TYPE_CODE, 'CBI' ISSUER_CODE, 'PROVISIONAL-RIAL-FEE-1405' CIRCULAR_NO, 'کارمزد خدمات بانکی ریالی - مصوبه جدید (مرجع موقت)' TITLE_FA, 'CBI Rial Banking Fees - Provisional Reference' TITLE_EN, DATE '2026-09-10' ISSUE_DATE, DATE '2026-09-10' EFFECTIVE_FROM, 'پیوست (کارمزدهای ریالی).pdf | کارمزدهای ریالی تفکیک ساختاری برای درج دیتابیس v3 2026-09-10.xlsx | XLSX_SHA256=bbe79ea223fabbfcddd83a402a70bc87f9c3fb3ad3d0de01369155240e4bd15e' DOCUMENT_REF, 'SHA256:ea2e6a22e3b92b7ea6ef5da8cd6bfa20f918d0fc069c2e1bd46b89167a993e14' DOCUMENT_HASH, 'PROVISIONAL' STATUS_CODE FROM dual) s
ON (t.SOURCE_CODE=s.SOURCE_CODE)
WHEN MATCHED THEN UPDATE SET t.SOURCE_TYPE_CODE=s.SOURCE_TYPE_CODE,t.ISSUER_CODE=s.ISSUER_CODE,t.CIRCULAR_NO=s.CIRCULAR_NO,t.TITLE_FA=s.TITLE_FA,t.TITLE_EN=s.TITLE_EN,t.ISSUE_DATE=s.ISSUE_DATE,t.EFFECTIVE_FROM=s.EFFECTIVE_FROM,t.EFFECTIVE_TO=NULL,t.DOCUMENT_REF=s.DOCUMENT_REF,t.DOCUMENT_HASH=s.DOCUMENT_HASH,t.STATUS_CODE=s.STATUS_CODE,t.UPDATED_AT=SYSTIMESTAMP,t.UPDATED_BY='CBI_1405_PROVISIONAL_IMPORT',t.RECORD_VERSION=t.RECORD_VERSION+1
WHEN NOT MATCHED THEN INSERT (SOURCE_CODE,SOURCE_TYPE_CODE,ISSUER_CODE,CIRCULAR_NO,TITLE_FA,TITLE_EN,ISSUE_DATE,EFFECTIVE_FROM,DOCUMENT_REF,DOCUMENT_HASH,STATUS_CODE,CREATED_BY)
VALUES (s.SOURCE_CODE,s.SOURCE_TYPE_CODE,s.ISSUER_CODE,s.CIRCULAR_NO,s.TITLE_FA,s.TITLE_EN,s.ISSUE_DATE,s.EFFECTIVE_FROM,s.DOCUMENT_REF,s.DOCUMENT_HASH,s.STATUS_CODE,'CBI_1405_PROVISIONAL_IMPORT');

PROMPT [CBI1405-P] Upserting provisional policy and version ...
MERGE INTO FEE_POLICY_SET t USING (SELECT 'CBI_RIAL_BANKING_1405_PROVISIONAL' POLICY_CODE,'سیاست کارمزد خدمات بانکی ریالی ۱۴۰۵ - موقت' NAME_FA,'CBI Rial Banking Fee Policy 1405 - Provisional' NAME_EN,'REGULATORY' POLICY_TYPE_CODE,'CBI' OWNER_ORG_CODE FROM dual) s ON (t.POLICY_CODE=s.POLICY_CODE)
WHEN MATCHED THEN UPDATE SET t.NAME_FA=s.NAME_FA,t.NAME_EN=s.NAME_EN,t.POLICY_TYPE_CODE=s.POLICY_TYPE_CODE,t.DESCRIPTION='مرجع موقت تا زمان دریافت نامه رسمی؛ جایگزین فقط دامنه کارمزدهای خدمات بانکی ریالی غیرالکترونیکی',t.OWNER_ORG_CODE=s.OWNER_ORG_CODE,t.STATUS_CODE='ACTIVE',t.UPDATED_AT=SYSTIMESTAMP,t.UPDATED_BY='CBI_1405_PROVISIONAL_IMPORT',t.RECORD_VERSION=t.RECORD_VERSION+1
WHEN NOT MATCHED THEN INSERT (POLICY_CODE,NAME_FA,NAME_EN,POLICY_TYPE_CODE,DESCRIPTION,OWNER_ORG_CODE,STATUS_CODE,CREATED_BY) VALUES (s.POLICY_CODE,s.NAME_FA,s.NAME_EN,s.POLICY_TYPE_CODE,'مرجع موقت تا زمان دریافت نامه رسمی؛ جایگزین فقط دامنه کارمزدهای خدمات بانکی ریالی غیرالکترونیکی',s.OWNER_ORG_CODE,'ACTIVE','CBI_1405_PROVISIONAL_IMPORT');
MERGE INTO FEE_POLICY_VERSION t USING (SELECT (SELECT POLICY_SET_ID FROM FEE_POLICY_SET WHERE POLICY_CODE='CBI_RIAL_BANKING_1405_PROVISIONAL') POLICY_SET_ID,'1405.P1' VERSION_NO FROM dual) s ON (t.POLICY_SET_ID=s.POLICY_SET_ID AND t.VERSION_NO=s.VERSION_NO)
WHEN MATCHED THEN UPDATE SET t.VERSION_TYPE_CODE='MAJOR',t.STATUS_CODE='ACTIVE',t.EFFECTIVE_FROM=DATE '2026-09-10',t.EFFECTIVE_TO=NULL,t.APPROVED_AT=SYSTIMESTAMP,t.APPROVED_BY='PROVISIONAL',t.ACTIVATED_AT=SYSTIMESTAMP,t.ACTIVATED_BY='PROVISIONAL',t.POLICY_HASH='bbe79ea223fabbfcddd83a402a70bc87f9c3fb3ad3d0de01369155240e4bd15e',t.CHANGE_SUMMARY='مصوبه موقت برگرفته از پیوست ۸ صفحه‌ای و فایل ساختاری ۱۵۲ تعرفه؛ تاریخ/شماره رسمی در دسترس نیست',t.UPDATED_AT=SYSTIMESTAMP,t.UPDATED_BY='CBI_1405_PROVISIONAL_IMPORT',t.RECORD_VERSION=t.RECORD_VERSION+1
WHEN NOT MATCHED THEN INSERT (POLICY_SET_ID,VERSION_NO,VERSION_TYPE_CODE,STATUS_CODE,EFFECTIVE_FROM,APPROVED_AT,APPROVED_BY,ACTIVATED_AT,ACTIVATED_BY,POLICY_HASH,CHANGE_SUMMARY,CREATED_BY) VALUES (s.POLICY_SET_ID,s.VERSION_NO,'MAJOR','ACTIVE',DATE '2026-09-10',SYSTIMESTAMP,'PROVISIONAL',SYSTIMESTAMP,'PROVISIONAL','bbe79ea223fabbfcddd83a402a70bc87f9c3fb3ad3d0de01369155240e4bd15e','مصوبه موقت برگرفته از پیوست ۸ صفحه‌ای و فایل ساختاری ۱۵۲ تعرفه؛ تاریخ/شماره رسمی در دسترس نیست','CBI_1405_PROVISIONAL_IMPORT');

PROMPT [CBI1405-P] Closing only prior non-electronic rial fee definition versions ...
UPDATE FEE_DEFINITION_VERSION dv SET dv.STATUS_CODE='SUPERSEDED', dv.EFFECTIVE_TO=DATE '2026-09-09', dv.UPDATED_AT=SYSTIMESTAMP, dv.UPDATED_BY='CBI_1405_PROVISIONAL_IMPORT', dv.RECORD_VERSION=dv.RECORD_VERSION+1 WHERE dv.REGULATORY_SOURCE_ID=(SELECT REGULATORY_SOURCE_ID FROM FEE_REGULATORY_SOURCE WHERE SOURCE_CODE='CBI_FEE_1404_04_35500') AND dv.VERSION_NO='1.0' AND EXISTS (SELECT 1 FROM FEE_DEFINITION d JOIN FEE_FEATURE f ON f.FEE_FEATURE_ID=d.FEE_FEATURE_ID WHERE d.FEE_DEFINITION_ID=dv.FEE_DEFINITION_ID AND f.FEATURE_CODE IN ('CBI_GUARANTEE_FEE_GROUP', 'CBI_REMITTANCE_FEE_GROUP', 'CBI_SAFE_DEPOSIT_FEE_GROUP', 'CBI_SECURITIES_FEE_GROUP', 'CBI_BILL_COLLECTION_FEE_GROUP', 'CBI_CURRENT_ACCOUNT_FEE_GROUP', 'CBI_SAVINGS_DEPOSIT_FEE_GROUP', 'CBI_CERTIFICATE_FEE_GROUP', 'CBI_STATEMENT_FEE_GROUP', 'CBI_ACCOUNT_SERVICE_FEE_GROUP', 'CBI_APPRAISAL_FEE_GROUP', 'CBI_CREDIT_FEE_GROUP', 'CBI_OTHER_SERVICE_FEE_GROUP') ) AND (dv.EFFECTIVE_TO IS NULL OR dv.EFFECTIVE_TO>DATE '2026-09-09');
UPDATE FEE_CALCULATION_RULE r SET r.EFFECTIVE_TO=DATE '2026-09-09', r.UPDATED_AT=SYSTIMESTAMP, r.UPDATED_BY='CBI_1405_PROVISIONAL_IMPORT', r.RECORD_VERSION=r.RECORD_VERSION+1 WHERE EXISTS (SELECT 1 FROM FEE_DEFINITION_VERSION dv JOIN FEE_DEFINITION d ON d.FEE_DEFINITION_ID=dv.FEE_DEFINITION_ID JOIN FEE_FEATURE f ON f.FEE_FEATURE_ID=d.FEE_FEATURE_ID JOIN FEE_REGULATORY_SOURCE rs ON rs.REGULATORY_SOURCE_ID=dv.REGULATORY_SOURCE_ID WHERE dv.FEE_DEFINITION_VERSION_ID=r.FEE_DEFINITION_VERSION_ID AND rs.SOURCE_CODE='CBI_FEE_1404_04_35500' AND dv.VERSION_NO='1.0' AND f.FEATURE_CODE IN ('CBI_GUARANTEE_FEE_GROUP', 'CBI_REMITTANCE_FEE_GROUP', 'CBI_SAFE_DEPOSIT_FEE_GROUP', 'CBI_SECURITIES_FEE_GROUP', 'CBI_BILL_COLLECTION_FEE_GROUP', 'CBI_CURRENT_ACCOUNT_FEE_GROUP', 'CBI_SAVINGS_DEPOSIT_FEE_GROUP', 'CBI_CERTIFICATE_FEE_GROUP', 'CBI_STATEMENT_FEE_GROUP', 'CBI_ACCOUNT_SERVICE_FEE_GROUP', 'CBI_APPRAISAL_FEE_GROUP', 'CBI_CREDIT_FEE_GROUP', 'CBI_OTHER_SERVICE_FEE_GROUP') ) AND (r.EFFECTIVE_TO IS NULL OR r.EFFECTIVE_TO>DATE '2026-09-09');

