PROMPT [CBI1405-P] Upserting 152 fee definitions, versions and calculation rules ...
MERGE INTO FEE_DEFINITION t USING (SELECT (SELECT FEE_FEATURE_ID FROM FEE_FEATURE WHERE FEATURE_CODE='CBI_RIAL_1405_GUARANTEE_GROUP') FEE_FEATURE_ID,'CBI1405R_GAR_1_1' FEE_CODE,'ضمانتنامه در مقابل 100 درصد سپرده نقدی' NAME_FA,'CBI1405R_GAR' CATEGORY_CODE,'CBI_1405_RIAL_PROVISIONAL' CLASSIFICATION_CODE,'منبع موقت کارمزد خدمات بانکی ریالی ۱۴۰۵ | سرفصل 1: صدور، تمدید، تقلیل، انتقال و ابطال ضمانتنامه شرکت در مناقصه، مزایده و سایر ضمانتنامه ها | ردیف تعرفه: 1-1 | صفحه PDF: 1 | متن مصوب: مقطوع 1,300,000 ریال' DESCRIPTION FROM dual) s ON (t.FEE_CODE=s.FEE_CODE)
WHEN MATCHED THEN UPDATE SET t.FEE_FEATURE_ID=s.FEE_FEATURE_ID,t.NAME_FA=s.NAME_FA,t.CATEGORY_CODE=s.CATEGORY_CODE,t.CLASSIFICATION_CODE=s.CLASSIFICATION_CODE,t.DESCRIPTION=s.DESCRIPTION,t.IS_ACTIVE='Y',t.UPDATED_AT=SYSTIMESTAMP,t.UPDATED_BY='CBI_1405_PROVISIONAL_IMPORT',t.RECORD_VERSION=t.RECORD_VERSION+1
